import{_ as r,o,c as n,ag as d}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-数据库-事务与并发","description":"","frontmatter":{"title":"架构师-备考 综合知识-数据库-事务与并发"},"headers":[],"relativePath":"综合知识/数据库/事务与并发.md","filePath":"综合知识/数据库/事务与并发.md","lastUpdated":null}'),a={name:"综合知识/数据库/事务与并发.md"};function e(s,t,l,i,g,h){return o(),n("div",null,[...t[0]||(t[0]=[d('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 事务 ACID 特性</li><li>[x] 并发控制问题（丢失更新/不可重复读/读脏数据）</li><li>[x] 封锁协议（X锁/S锁/三级封锁协议）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、事务-acid-特性" tabindex="-1">一、事务 ACID 特性 <a class="header-anchor" href="#一、事务-acid-特性" aria-label="Permalink to &quot;一、事务 ACID 特性&quot;">​</a></h3><blockquote><p><strong>事务</strong>：由一系列操作组成，这些操作要么全做，要么全不做。</p></blockquote><table tabindex="0"><thead><tr><th>特性</th><th>含义</th><th>记忆口诀</th></tr></thead><tbody><tr><td><strong>原子性</strong>（Atomicity）</td><td>要么全做，要么全不做</td><td><strong>操作</strong>层面</td></tr><tr><td><strong>一致性</strong>（Consistency）</td><td>事务发生后数据是一致的（如转账，A扣钱B必到账）</td><td><strong>数据</strong>层面</td></tr><tr><td><strong>隔离性</strong>（Isolation）</td><td>任一事务的更新操作直到其成功提交的整个过程对其他事务都是不可见的</td><td><strong>执行</strong>层面</td></tr><tr><td><strong>持久性</strong>（Durability）</td><td>事务操作的结果是持续性的</td><td><strong>改变</strong>层面</td></tr></tbody></table><hr><h3 id="二、并发控制问题" tabindex="-1">二、并发控制问题 <a class="header-anchor" href="#二、并发控制问题" aria-label="Permalink to &quot;二、并发控制问题&quot;">​</a></h3><blockquote><p>事务是并发控制的前提条件，并发控制就是<strong>控制不同的事务并发执行</strong>，提高系统效率。但并发控制中存在以下三个问题：</p></blockquote><table tabindex="0"><thead><tr><th>问题</th><th>描述</th><th>场景示例</th></tr></thead><tbody><tr><td><strong>丢失更新</strong></td><td>事务1对数据A修改写回，事务2也对A修改写回，事务2覆盖事务1的更新</td><td>两个事务同时修改同一数据</td></tr><tr><td><strong>不可重复读</strong></td><td>事务2读A，事务1修改A并写回，事务2再次读A发现数据不对</td><td>同一个事务两次读取结果不同</td></tr><tr><td><strong>读脏数据</strong></td><td>事务1修改A，事务2读取A，事务1回滚，事务2读到的是无效数据</td><td>读取了未提交的修改</td></tr></tbody></table><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830233338.png" alt="并发问题示意"></p><hr><h3 id="三、封锁协议" tabindex="-1">三、封锁协议 <a class="header-anchor" href="#三、封锁协议" aria-label="Permalink to &quot;三、封锁协议&quot;">​</a></h3><p><strong>锁类型：</strong></p><ul><li><strong>X 锁（排他锁 / 写锁）</strong>：若事务 T 对数据对象 A 加上 X 锁，则<strong>只允许 T 读取和修改 A</strong>，其他事务都不能再对 A 加任何类型的锁，直到 T 释放 A 上的锁。</li><li><strong>S 锁（共享锁 / 读锁）</strong>：若事务 T 对数据对象 A 加上 S 锁，则只允许 T 读取 A（不能修改），<strong>其他事务只能再对 A 加 S 锁</strong>（能读不能修改），直到 T 释放 A 上的 S 锁。</li></ul><p><strong>三级封锁协议：</strong></p><table tabindex="0"><thead><tr><th>级别</th><th>规则</th><th style="text-align:center;">可解决问题</th></tr></thead><tbody><tr><td><strong>一级封锁协议</strong></td><td>事务在<strong>修改数据 R 之前必须先对其加 X 锁</strong>，直到事务结束才释放</td><td style="text-align:center;">丢失更新</td></tr><tr><td><strong>二级封锁协议</strong></td><td>一级 + 事务在<strong>读数据 R 之前必须先对其加 S 锁</strong>，读完后即可释放 S 锁</td><td style="text-align:center;">丢失更新、读脏数据</td></tr><tr><td><strong>三级封锁协议</strong></td><td>一级 + 事务在<strong>读取数据 R 之前先对其加 S 锁，直到事务结束才释放</strong></td><td style="text-align:center;">丢失更新、读脏数据、不可重复读</td></tr></tbody></table><blockquote><p><strong>记忆要点</strong>：三级封锁协议的核心区别在于 S 锁的<strong>释放时机</strong>。二级是读完即释放，三级是事务结束才释放。级别越高，并发度越低。</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830233639.png" alt="三级封锁协议示意"></p>',19)])])}const u=r(a,[["render",e]]);export{b as __pageData,u as default};
